llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Ethinylestradiol, a close estrane analog with a 17α-ethinyl-17β-ol tertiary alcohol and phenolic A-ring, had absolute oral bioavailability of 62 ± 4.4% in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Estradiol, which differs from the query by having a secondary 17β-OH, had absolute oral bioavailability of about 5% in humans; this low value reflects rapid 17-oxidation and is less applicable to the query's fully substituted C17 alcohol.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "Estetrol, a polyhydroxylated estrane steroid, showed high and dose-related oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Moxestrol, a 17α-ethinyl estradiol derivative, had absolute oral bioavailability of 35% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "The closest-scoring steroid analogue record reports oral bioavailability of about 25-65%, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic estrane steroid with a phenol and a fully substituted C17 alcohol. The closest high-F analogues (ethinylestradiol, estetrol, moxestrol) share the metabolically protected C17 tertiary alcohol and show F ≥35%, while estradiol's low F is tied to its oxidizable secondary 17-OH. The balance favors F ≥20%.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "The exact metabolic fate of the cyclopropyl-containing C17 substituent is unknown.",
    "Gut-wall conjugation and solubility of this lipophilic neutral steroid are not experimentally characterized.",
    "The closest analogue record (C15) is ambiguous about whether it refers to estrone or ethinylestradiol."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

